schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/sdd/ui-ux-design.json",
  "title": "ui-ux-design.md (per-feature design doc)",
  "type": "object",
  "required": ["feature_id", "path", "intent", "layout", "states", "nielsen_audit", "norman_audit", "copy"],
  "additionalProperties": false,
  "definitions": {
    "audit_row": {
      "type": "object",
      "required": ["finding", "fix_or_ok"],
      "properties": {
        "finding": {"type": "string", "minLength": 1},
        "fix_or_ok": {"type": "string", "minLength": 1}
      }
    }
  },
  "properties": {
    "feature_id": {"type": "string", "pattern": "^F[0-9]{3,}$"},
    "path": {"type": "string", "pattern": "^features/in-progress/F[0-9]{3,}-[a-z0-9-]+/ui-ux-design\\.md$"},
    "intent": {"type": "string", "minLength": 1},
    "layout": {"type": "string", "minLength": 1},
    "states": {
      "type": "object",
      "required": ["empty", "loading", "error", "success", "disabled"],
      "additionalProperties": false,
      "properties": {
        "empty": {"type": "string", "minLength": 1},
        "loading": {"type": "string", "minLength": 1},
        "error": {"type": "string", "minLength": 1},
        "success": {"type": "string", "minLength": 1},
        "disabled": {"type": "string", "minLength": 1}
      }
    },
    "nielsen_audit": {
      "type": "array",
      "minItems": 5,
      "maxItems": 5,
      "uniqueItems": true,
      "items": {
        "allOf": [
          {"$ref": "#/definitions/audit_row"},
          {"required": ["heuristic"], "properties": {"heuristic": {"type": "string", "enum": ["N1", "N3", "N4", "N5", "N6"]}}}
        ]
      }
    },
    "norman_audit": {
      "type": "array",
      "minItems": 2,
      "maxItems": 2,
      "uniqueItems": true,
      "items": {
        "allOf": [
          {"$ref": "#/definitions/audit_row"},
          {"required": ["principle"], "properties": {"principle": {"type": "string", "enum": ["affordance", "feedback"]}}}
        ]
      }
    },
    "copy": {
      "type": "object",
      "required": ["primary_button", "empty_state", "error_message", "success_message"],
      "properties": {
        "primary_button": {"type": "string", "minLength": 1},
        "secondary_button": {"type": "string"},
        "empty_state": {"type": "string", "minLength": 1},
        "error_message": {"type": "string", "minLength": 1},
        "success_message": {"type": "string", "minLength": 1}
      }
    }
  }
}

output-contract.example:
{
  "feature_id": "F021",
  "path": "features/in-progress/F021-upgrade-page/ui-ux-design.md",
  "intent": "A signed-in free-tier user upgrades to the solo tier without leaving the account area.",
  "layout": "Plan cards in a single row above a Stripe Elements form; primary button below the form, secondary 'Back to account' link under it.",
  "states": {
    "empty": "No plan selected: cards shown, form hidden, primary button disabled with tooltip 'Pick a plan'.",
    "loading": "After submit: button disabled with spinner, form fields read-only.",
    "error": "Inline error under the card field; form stays editable; no charge created.",
    "success": "Redirect to /account?upgraded=solo with success toast.",
    "disabled": "Card already on file and subscription active: cards greyed out, note 'You are already on solo'."
  },
  "nielsen_audit": [
    {"heuristic": "N1", "finding": "Spinner and read-only fields show the submit is in flight.", "fix_or_ok": "noted OK"},
    {"heuristic": "N3", "finding": "No way to cancel once submit was clicked.", "fix_or_ok": "add 30s timeout with 'Connection lost. Try again.' toast"},
    {"heuristic": "N4", "finding": "'Upgrade' in nav vs 'Choose plan' on the button.", "fix_or_ok": "rename button to 'Upgrade to Solo'"},
    {"heuristic": "N5", "finding": "Card number accepts letters until submit.", "fix_or_ok": "Stripe Elements input mask"},
    {"heuristic": "N6", "finding": "Selected plan name repeated above the form.", "fix_or_ok": "noted OK"}
  ],
  "norman_audit": [
    {"principle": "affordance", "finding": "Plan cards are clickable but only the radio is styled.", "fix_or_ok": "hover + cursor:pointer on the whole card"},
    {"principle": "feedback", "finding": "Submit disables the button and shows a spinner immediately.", "fix_or_ok": "noted OK"}
  ],
  "copy": {
    "primary_button": "Upgrade to Solo",
    "secondary_button": "Back to account",
    "empty_state": "Pick a plan to continue.",
    "error_message": "Your card was declined.",
    "success_message": "You are on Solo now."
  }
}
